  const group = 'gb:light-active:flex gb:light-active:flex-wrap gb:light-active:gap-1.5';
  const base = 'sun-session-ctl gb:light-active:inline-flex gb:light-active:items-center gb:light-active:justify-center gb:light-active:gap-1 gb:light-active:[@media(pointer:coarse)]:min-h-11 gb:light-active:max-[480px]:min-h-11 gb:light-active:[@media(pointer:coarse)]:min-w-11 gb:light-active:max-[480px]:min-w-11 gb:light-active:px-2.5 gb:light-active:py-1 gb:light-active:border gb:light-active:border-line gb:light-active:rounded-full gb:light-active:text-[11px] gb:light-active:cursor-pointer gb:light-active:hover:border-accent gb:light-active:focus-visible:outline-2 gb:light-active:focus-visible:outline-accent gb:light-active:disabled:cursor-default';
  const control = base + ' gb:light-active:bg-secondary-surface gb:light-active:text-ink';
</script>
<div class="sun-session-active-controls gb:light-active:flex gb:light-active:flex-wrap gb:light-active:gap-x-3 gb:light-active:gap-y-2 gb:light-active:mt-2 gb:light-active:mb-1" data-sun-session-action={view.kind === 'sun' ? 'ignore' : undefined} data-light-devices-action={view.kind === 'device' ? 'suppress' : undefined}>
  <div class={`sun-session-ctl-primary ${group}`}>
