  </div>
  {#if view.kind === 'sun'}
    <div class={`sun-session-ctl-secondary ${group} gb:light-active:pl-2 gb:light-active:border-l gb:light-active:border-line gb:light-active:max-[480px]:pl-0 gb:light-active:max-[480px]:border-l-0`}>
